/**
 * Session / round state machine.
 *
 * This module owns the random number timing (see 03-core-mechanics.md 3.1).
 * Components MUST NOT call generateTarget() directly; they MUST go through
 * the functions in this file.
 *
 * Invariants enforced:
 *   1. target is generated by `enterNewRound()` synchronously upon round
 *      creation, BEFORE any GUESSING input.
 *   2. target is never re-generated for an existing round.
 *   3. target is only read (not mutated) when computing `correct`.
 *   4. ABANDONED rounds do not count toward k/n.
 *
 * All functions are pure: they take a Session and return a new Session.
 */

import { generateTarget } from './rng.js'
import { DEFAULT_SESSION_SETTINGS } from './statistics.js'

const newId = () =>
  (typeof crypto !== 'undefined' && crypto.randomUUID
    ? crypto.randomUUID()
    : 'xxxxxxxx-xxxx-4xxx-yxxx-xxxxxxxxxxxx'.replace(/[xy]/g, (c) => {
        const r = (Math.random() * 16) | 0
        const v = c === 'x' ? r : (r & 0x3) | 0x8
        return v.toString(16)
      }))

const DEFAULT_SETTINGS = DEFAULT_SESSION_SETTINGS

/**
 * Begin a new session. A fresh session has zero rounds; the first round
 * is materialised by the App calling `enterNewRound()` immediately
 * afterwards.
 *
 * @returns {import('./schema.js').Session}
 */
export function beginSession(opts) {
  const settings = { ...DEFAULT_SETTINGS, ...(opts || {}) }
  return {
    id: newId(),
    createdAt: Date.now(),
    completedAt: null,
    status: 'IN_PROGRESS',
    rounds: [],
    settings,
  }
}

/**
 * Create a new round with a freshly generated target.
 *
 * Returns a new session with an additional round appended, in TARGET_READY.
 *
 * @param {import('./schema.js').Session} session
 * @returns {import('./schema.js').Session}
 */
export function enterNewRound(session) {
  if (!session) throw new Error('enterNewRound: session required')
  if (session.status !== 'IN_PROGRESS') {
    throw new Error(
      `enterNewRound: cannot add round to session in status ${session.status}`,
    )
  }
  if (session.rounds.length >= session.settings.roundsPerSession) {
    throw new Error('enterNewRound: session already has full round count')
  }

  // CRITICAL: target generated here, BEFORE user sees or interacts with the round.
  const id = newId()
  const index = session.rounds.length
  const target = generateTarget(id)

  const round = {
    id,
    index,
    target, // frozen — never reassigned after this point
    createdAt: Date.now(),
    guess: null,
    status: 'TARGET_READY',
    correct: null,
    revealedAt: null,
  }
  Object.freeze(round)

  return {
    ...session,
    rounds: [...session.rounds, round],
  }
}

function replaceRound(session, roundId, patch) {
  let found = false
  const next = session.rounds.map((r) => {
    if (r.id !== roundId) return r
    found = true
    return { ...r, ...patch }
  })
  if (!found) throw new Error(`replaceRound: round ${roundId} not found`)
  return { ...session, rounds: next }
}

/**
 * Set a tentative guess; round transitions TARGET_READY -> GUESSING.
 * If a guess is already set, this updates it.
 *
 * @param {import('./schema.js').Session} session
 * @param {string} roundId
 * @param {1|2|3|4|5} guess
 */
export function previewGuess(session, roundId, guess) {
  const r = session.rounds.find((x) => x.id === roundId)
  if (!r) throw new Error(`previewGuess: round ${roundId} not found`)
  if (r.status !== 'TARGET_READY') {
    throw new Error(`previewGuess: round in status ${r.status}`)
  }
  return replaceRound(session, roundId, {
    guess,
    status: 'GUESSING',
  })
}

/**
 * Commit the user's guess and reveal. Round transitions to REVEALED.
 *
 * IMPORTANT: target is read here, NEVER regenerated.
 *
 * @param {import('./schema.js').Session} session
 * @param {string} roundId
 * @param {1|2|3|4|5} guess
 */
export function submitGuess(session, roundId, guess) {
  const r = session.rounds.find((x) => x.id === roundId)
  if (!r) throw new Error(`submitGuess: round ${roundId} not found`)
  if (r.status !== 'TARGET_READY' && r.status !== 'GUESSING') {
    throw new Error(`submitGuess: round in status ${r.status}`)
  }
  const correct = guess === r.target
  return replaceRound(session, roundId, {
    guess,
    status: 'REVEALED',
    correct,
    revealedAt: Date.now(),
  })
}

/**
 * Cancel a round (mark as ABANDONED).
 *
 * @param {import('./schema.js').Session} session
 * @param {string} roundId
 */
export function abandonRound(session, roundId) {
  const r = session.rounds.find((x) => x.id === roundId)
  if (!r) throw new Error(`abandonRound: round ${roundId} not found`)
  if (r.status === 'REVEALED' || r.status === 'ABANDONED') {
    throw new Error(`abandonRound: round already in terminal status ${r.status}`)
  }
  return replaceRound(session, roundId, { status: 'ABANDONED' })
}

/**
 * Mark session as COMPLETED and attach a summary.
 *
 * @param {import('./schema.js').Session} session
 * @param {import('./schema.js').SessionSummary} summary
 */
export function completeSession(session, summary) {
  if (session.status !== 'IN_PROGRESS') {
    throw new Error(`completeSession: session in status ${session.status}`)
  }
  return {
    ...session,
    status: 'COMPLETED',
    completedAt: Date.now(),
    summary,
  }
}

/**
 * Mark session as ABANDONED.
 */
export function abandonSession(session) {
  if (session.status !== 'IN_PROGRESS') return session
  // Mark any non-terminal round as ABANDONED
  let mutated = session
  for (const r of session.rounds) {
    if (r.status !== 'REVEALED' && r.status !== 'ABANDONED') {
      mutated = abandonRound(mutated, r.id)
    }
  }
  return { ...mutated, status: 'ABANDONED' }
}

/**
 * Find the round that the UI should currently be rendering.
 *
 * Priorities:
 *   1. The first TARGET_READY or GUESSING round (the round the user is in).
 *   2. Otherwise, the most recent REVEALED round (so the feedback panel stays
 *      visible until the user clicks "下一题" or auto-advances).
 *   3. Otherwise null (no rounds yet, or session has been abandoned).
 */
export function findActiveRound(session) {
  if (!session) return null
  let lastRevealed = null
  for (const r of session.rounds) {
    if (r.status === 'TARGET_READY' || r.status === 'GUESSING') return r
    if (r.status === 'REVEALED') lastRevealed = r
  }
  return lastRevealed
}
